// Simulación en un solo proceso: la misma tarea (recibir pedidos y asignarlos) con dos arquitecturas.
function rng(seed){ let s=seed>>>0; return ()=>{ s=(s+0x6D2B79F5)>>>0; let t=s; t=Math.imul(t^(t>>>15),t|1); t^=t+Math.imul(t^(t>>>7),t|61); return ((t^(t>>>14))>>>0)/4294967296; }; }

function simular(nombre, cfg){
  const r = rng(42);
  const TICKS = 600;            // 1 tick = 1 segundo simulado
  const CAIDA_EN = 200;         // el nodo 0 se cae en el segundo 200
  const REINICIO = 90;          // y tarda 90 s en volver
  let cola = [], enMemoria = cfg.durable ? null : [];
  const nodos = Array.from({length: cfg.nodos}, () => ({ vivoDesde: 0, ocupadoHasta: 0 }));
  let llegaron = 0, entregados = 0, perdidos = 0, rechazados = 0; const esperas = [];
  for (let t = 0; t < TICKS; t++) {
    const caido = t >= CAIDA_EN && t < CAIDA_EN + REINICIO;
    if (t === CAIDA_EN && !cfg.durable) { perdidos += cola.length; cola = []; }   // la memoria se pierde con el proceso
    // llegan en promedio 0,5 pedidos por segundo, más una ráfaga justo antes de la caída
    const rafaga = t >= 180 && t < 200 ? 3 : 0;      // a las 8:03 entra la tanda de la mañana
    const n = rafaga + (r() < 0.1 ? 2 : r() < 0.3 ? 1 : 0);
    for (let i = 0; i < n; i++) {
      llegaron++;
      const sinNodoVivo = cfg.nodos === 1 && caido;
      if (sinNodoVivo) { rechazados++; continue; }         // nadie atiende: el cliente ve un error
      cola.push(t);
    }
    nodos.forEach((nd, i) => {
      const vivo = !(i === 0 && caido);
      if (vivo && nd.ocupadoHasta <= t && cola.length) { const llego = cola.shift(); nd.ocupadoHasta = t + 2; entregados++; esperas.push(t - llego); }
    });
  }
  esperas.sort((a,b)=>a-b);
  const p95 = esperas[Math.floor(esperas.length*0.95)];
  console.log(nombre.padEnd(34), 'llegaron', llegaron, '| atendidos', entregados, '| perdidos', perdidos, '| rechazados', rechazados, '| espera p95', p95, 's | nodos', cfg.nodos, '| piezas a operar', cfg.costo);
}
simular('A: un proceso, todo en memoria', { nodos: 1, durable: false, costo: 1 });
simular('B: cola durable + 2 trabajadores', { nodos: 2, durable: true, costo: 3 });
